{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "LBH Shipping Vessel Extraction",
  "description": "Structured extraction of vessel and cargo data from emails",
  "type": "object",
  "properties": {
    "vessels": {
      "type": "array",
      "description": "Array of vessels mentioned in the email",
      "minItems": 1,
      "items": {
        "type": "object",
        "properties": {
          "vessel": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "Vessel name or TBN"
              },
              "imo": {
                "type": ["string", "null"],
                "description": "IMO number"
              },
              "grt": {
                "type": ["number", "null"],
                "description": "Gross tonnage (numbers only)"
              },
              "dwt": {
                "type": ["number", "null"],
                "description": "Deadweight tonnage (numbers only)"
              },
              "loa": {
                "type": ["number", "null"],
                "description": "Length overall in meters (numbers only)"
              },
              "beam": {
                "type": ["number", "null"],
                "description": "Beam in meters"
              },
              "draft": {
                "type": ["number", "null"],
                "description": "Draft in meters"
              },
              "flag": {
                "type": ["string", "null"],
                "description": "Vessel flag state"
              }
            },
            "required": ["name"]
          },
          "cargo": {
            "type": "object",
            "properties": {
              "operation_type": {
                "type": ["string", "null"],
                "enum": ["Loading", "Discharge", "STS", "Bunkering", null],
                "description": "Type of operation"
              },
              "cargo_type": {
                "type": ["string", "null"],
                "description": "Full cargo description"
              },
              "quantity": {
                "type": ["number", "null"],
                "description": "Cargo quantity in MT (numbers only)"
              }
            }
          },
          "port": {
            "type": "object",
            "properties": {
              "port": {
                "type": ["string", "null"],
                "description": "Port name"
              },
              "country": {
                "type": ["string", "null"],
                "description": "Country"
              },
              "terminal": {
                "type": ["string", "null"],
                "description": "Terminal mentioned by client (even if incorrect)"
              }
            }
          },
          "contact": {
            "type": "object",
            "properties": {
              "email": {
                "type": ["string", "null"],
                "description": "Contact email"
              },
              "name": {
                "type": ["string", "null"],
                "description": "Contact person name"
              },
              "company": {
                "type": ["string", "null"],
                "description": "Company name"
              }
            }
          },
          "other": {
            "type": "object",
            "properties": {
              "eta": {
                "type": ["string", "null"],
                "description": "Estimated time of arrival"
              },
              "special_requirements": {
                "type": ["string", "null"],
                "description": "Special requirements"
              },
              "notes": {
                "type": ["string", "null"],
                "description": "Additional notes"
              }
            }
          }
        },
        "required": ["vessel", "cargo", "port"]
      }
    }
  },
  "required": ["vessels"]
}

