// Flatten nested data for AI prompt
const allItems = $input.all();

const results = allItems.map(item => {
  const data = item.json;

  // Extract from nested or flattened structure
  const vessel = data.vessel || {};
  const cargo = data.cargo || {};
  const port = data.port || {};
  const contact = data.contact || {};

  return {
    // Vessel data (flattened)
    vessel_name: vessel.name || data.vessel_name || null,
    vessel_imo: vessel.imo || data.imo || null,
    vessel_flag: vessel.flag || data.flag || null,
    vessel_loa: vessel.loa || data.loa || null,
    vessel_beam: vessel.beam || data.beam || null,
    vessel_draft: vessel.draft || data.draft || null,
    vessel_grt: vessel.grt || data.grt || null,
    vessel_dwt: vessel.dwt || data.dwt || null,

    // Cargo data (flattened)
    operation_type: cargo.operation_type || data.operation_type || null,
    cargo_type: cargo.cargo_type || data.cargo_type || null,
    cargo_quantity: cargo.quantity || data.cargo_quantity || null,

    // Location data (flattened)
    port_name: port.port || data.port_name || null,
    country: port.country || data.country || null,
    area: data.area || null,
    terminal: data.terminal || null,
    facility: data.facility || null,
    port_code: data.port_code || null,

    // Contact data (flattened)
    company_name: contact.company || data.company_name || null,
    contact_name: contact.name || data.contact_name || null,
    contact_email: contact.email || data.contact_email || null,

    // Calculated values (from code nodes)
    port_stay: data.port_stay || null,
    tugs: data.tugs || null,
    loading_rate: data.loading_rate || null,

    // Original data for reference
    _original: data
  };
});

return results.map(r => ({ json: r }));

