};

const searchQuery = questions.length > 0
  ? questions.map(q => q.question).join('. ')
  : `cargo operations ${vesselData.cargo_type || ''} ${vesselData.terminal || ''} pricing terminal`;

console.log('🚢 Vessel:', vesselData.name, '| Query:', searchQuery);

return [{
