    .replace(/cura\u00e7ao/g, 'curacao')
    .replace(/curaçao/g, 'curacao')
    .replace(/\u2022/g, '-')  // • naar -
    .replace(/•/g, '-')        // extra check
    .replace(/\u00e7/g, 'c');
