  const loa = item.json.loa || 0;
  const portCode = item.json.port_code || '';
  const operation = (item.json.operation_type || '').toLowerCase();

  let tugs = 0;

  // Try Supabase match first
  const matchingRules = tugRules.filter(tr => {
    const trPort = (tr.port_code || '').toLowerCase();
    const currentPort = (portCode || '').toLowerCase();
    const loaMin = parseFloat(tr.loa_min) || 0;
    const loaMax = parseFloat(tr.loa_max) || 9999;

    const portMatch = currentPort === trPort || currentPort.includes(trPort) || trPort.includes(currentPort);
    const loaMatch = loa >= loaMin && loa <= loaMax;

    let opMatch = true;
    if (tr.operation_types && tr.operation_types.length > 0) {
      opMatch = tr.operation_types.some(ot => operation.includes(ot.toLowerCase()));
    }

    return portMatch && loaMatch && opMatch;
  });

  if (matchingRules.length > 0) {
    tugs = Math.max(...matchingRules.map(r => r.tug_count));
    console.log('✅ Supabase tug match: ' + portCode + ' + LOA ' + loa + 'm → ' + tugs + ' tugs');
  } else {
    // Fallback logic
    if (portCode.includes('OFFSHORE') || portCode.includes('ST_MICHIELS')) {
      if (operation.includes('sts') || operation.includes('ship-to-ship')) {
        tugs = loa > 200 ? 2 : 1;
      } else { tugs = 0; }
    } else if (portCode.includes('OUTER_BAYS')) {
      tugs = 0;
    } else if (loa >= 169) {
      tugs = 2;
    } else if (loa > 0) {
      tugs = 1;
    }
    console.log('⚠️ No Supabase tug rule for ' + portCode + ', fallback: ' + tugs);
  }

  return { ...item.json, tugs: tugs };
});

return results.map(r => ({ json: r }));

